schema_sdl:
directive @cost(weight: Float!) on FIELD_DEFINITION
directive @listSize(size: Int) on FIELD
type Query { me: User @cost(weight: 2) users(first: Int): [User!]! @cost(weight: 5) posts(limit: Int): [Post!]! @cost(weight: 4) }
type User { id: ID! @cost(weight: 1) name: String! @cost(weight: 1) friends(first: Int): [User!]! @cost(weight: 3) posts(limit: Int): [Post!]! @cost(weight: 4) }
type Post { id: ID! @cost(weight: 1) title: String! @cost(weight: 1) author: User @cost(weight: 2) }
